const NOTIF_SOUND_B64 = 'data:audio/mp3;base64,';


let _statusAnterior = {};  
let _statusPolling  = null;
let _notifAudio     = null;
let _audioUnlocked  = false;
let _notifAtivadas  = false;


function _getAudio() {
  if (!_notifAudio) { _notifAudio = new Audio(NOTIF_SOUND_B64); _notifAudio.volume = 0.85; }
  return _notifAudio;
}
function _unlockAudio() {
  if (_audioUnlocked) return;
  try { const a = _getAudio(); a.play().then(() => { a.pause(); a.currentTime = 0; _audioUnlocked = true; }).catch(() => {}); } catch(e) {}
}
document.addEventListener('click',     _unlockAudio, { passive: true });
document.addEventListener('touchstart', _unlockAudio, { passive: true });

function tocarSomNotificacao() {
  try {
    const a = _getAudio(); a.currentTime = 0;
    a.play().catch(() => setTimeout(() => { try { a.currentTime=0; a.play().catch(()=>{}); } catch(e){} }, 300));
  } catch(e) {}
}


async function ativarNotificacoes() {
  if (!('Notification' in window)) { showToast('Seu browser não suporta notificações.', 'error'); return; }
  const perm = await Notification.requestPermission();
  _notifAtivadas = (perm === 'granted');
  if (_notifAtivadas) {
    showToast('Notificações ativadas! ✅');
    _unlockAudio(); 
  } else {
    showToast('Permissão negada. O banner in-app ainda funcionará.', 'error');
  }
}

function _mostrarBanner(titulo, corpo) {
  document.getElementById('rango-notif-banner')?.remove();
  if (!document.getElementById('rng-notif-kf')) {
    const s = document.createElement('style'); s.id = 'rng-notif-kf';
    s.textContent = '@keyframes rngIn{from{opacity:0;transform:translateX(-50%) translateY(-24px)}to{opacity:1;transform:translateX(-50%) translateY(0)}}';
    document.head.appendChild(s);
  }
  const el = document.createElement('div');
  el.id = 'rango-notif-banner';
  el.innerHTML = '<div style="display:flex;align-items:flex-start;gap:10px">' +
    '<div style="font-size:1.5rem;line-height:1">' + titulo.split(' ')[0] + '</div>' +
    '<div style="flex:1"><div style="font-weight:700;font-size:.84rem;margin-bottom:2px">' + titulo.replace(/^\S+\s/,'') + '</div>' +
    '<div style="font-size:.76rem;opacity:.9;line-height:1.4">' + corpo + '</div></div>' +
    '<button onclick="document.getElementById(\'rango-notif-banner\').remove()" ' +
    'style="background:none;border:none;color:#fff;font-size:1rem;cursor:pointer;opacity:.8;padding:0">✕</button></div>';
  Object.assign(el.style, {
    position:'fixed', top:'16px', left:'50%', transform:'translateX(-50%)',
    zIndex:'99999', background:'linear-gradient(135deg,#ff7a00,#ff5500)',
    color:'#fff', padding:'14px 16px', borderRadius:'16px',
    boxShadow:'0 8px 32px rgba(255,122,0,.5)', maxWidth:'340px',
    width:'calc(100% - 32px)', animation:'rngIn .35s cubic-bezier(.22,1,.36,1)',
    fontFamily:"'DM Sans',sans-serif", cursor:'default',
  });
  document.body.appendChild(el);
  setTimeout(() => el?.remove(), 8000);
}

function _notifSistema(titulo, corpo) {
  if (typeof Notification === 'undefined' || Notification.permission !== 'granted') return;
  try {
    const n = new Notification(titulo, { body: corpo, icon: '/assets/img/rangologo.png', tag: 'rango-status', renotify: true });
    setTimeout(() => n.close(), 8000);
  } catch(e) {}
}


function verificarMudancasStatus(pedidos) {
  const msgs = {
    preparando: { t: '⏳ Pedido em preparo!',   b: code => 'Pedido ' + code + ' esta sendo preparado. Em breve ficara pronto!' },
    pronto:     { t: '✅ Pedido pronto!',        b: code => 'Pedido ' + code + ' esta pronto! Va ao balcao retirar. 🎉' },
  };
  let tocou = false;
  for (const p of pedidos) {
    const key      = String(p.id);
    const anterior = _statusAnterior[key];
    const atual    = p.status;
    if (anterior !== undefined && anterior !== atual && msgs[atual]) {
      const m = msgs[atual];
      const cod = p.codigo || ('#' + p.id);
      tocarSomNotificacao();
      _mostrarBanner(m.t, m.b(cod));
      _notifSistema(m.t, m.b(cod));
      tocou = true;
    }
    _statusAnterior[key] = atual;
  }
}


function iniciarPollingStatus() {
  if (_statusPolling) return;
  _statusPolling = setInterval(async () => {
    try {
      const res = await API.pedidos.meus();
      if (!res.ok) return;
      const ativos = res.dados.filter(p => !['entregue','cancelado'].includes(p.status));
      verificarMudancasStatus(ativos);
    } catch(e) {}
  }, 12000);
}

function pararPollingStatus() {
  clearInterval(_statusPolling);
  _statusPolling = null;
}

let usuario      = null;
let produtos     = [];
let categorias   = [];
let cart         = [];
let orders       = { pendentes: [], confirmados: [], historico: [] };
let rangoPoints  = 0;
let pontos_ganhos= 0;
let activeCategory   = 'Todos';

let _sugereProduto = null;

function _rangoGetContexto() {
  const h = new Date().getHours();
  if (h >= 6  && h < 10) return { periodo:'manhã',        emoji:'☕', hook:'Começar bem o dia faz toda a diferença!' };
  if (h >= 10 && h < 12) return { periodo:'lanche da manhã', emoji:'🥐', hook:'Aquela energia antes do intervalo?' };
  if (h >= 12 && h < 14) return { periodo:'almoço',       emoji:'🍽️', hook:'Hora de recarregar as energias!' };
  if (h >= 14 && h < 17) return { periodo:'tarde',        emoji:'🧃', hook:'Tarde produtiva começa com um bom lanche!' };
  if (h >= 17 && h < 20) return { periodo:'fim de tarde', emoji:'🍕', hook:'Mereceu esse gostoso no fim do dia!' };
  return { periodo:'noite', emoji:'🌙', hook:'Encerra o dia com algo especial!' };
}



function _selecionarProduto() {
  if (!produtos || !produtos.length) return null;
  const disponiveis = produtos.filter(p => p.em_estoque !== false && Number(p.estoque) > 0);
  if (!disponiveis.length) return null;
  const quentes = disponiveis.filter(p => parseFloat(p.preco) >= 5);
  const lista   = quentes.length ? quentes : disponiveis;
  return lista[Math.floor(Math.random() * lista.length)];
}

window.rangoSugereNovo = function rangoSugereNovo() {
  const titulo  = document.getElementById('rango-sugere-titulo');
  const texto   = document.getElementById('rango-sugere-texto');
  const imgEl   = document.getElementById('rango-sugere-img');
  const btn     = document.getElementById('rango-sugere-btn');
  const refresh = document.getElementById('rango-sugere-refresh');
  if (!titulo) return;

  const prod = _selecionarProduto();
  if (!prod) { titulo.textContent = 'Cardápio carregando...'; return; }
  _sugereProduto = prod;

  const ctx = _rangoGetContexto();

 
  const mensagens = {
    'manhã':              ['☕ Comece o dia com energia!', '🌅 Bom dia, bom lanche!', '🔥 Combustível pro primeiro tempo!', '🌤️ Manhã com mais sabor!'],
    'lanche da manhã':    ['⚡ Energia pro intervalo!', '🥐 Não passe fome no recreio!', '💪 Lanche poderoso!', '🕐 Hora do reforço!'],
    'almoço':             ['🍽️ Hora do almoço chegou!', '😋 Que tal esse hoje?', '🔋 Recarregue as energias!', '🌟 Destaque do almoço!'],
    'tarde':              ['🍕 Tarde com mais sabor!', '⭐ Destaque da tarde!', '🧃 Perfeito pra tarde!', '🎯 Escolha certa pra agora!'],
    'fim de tarde':       ['🌆 Final de dia gostoso!', '🏆 Você merece esse!', '✨ Última chance do dia!', '🎉 Encerra bem o dia!'],
    'noite':              ['🌙 Ceia especial!', '🍕 Boa pedida pra agora!', '⭐ Nosso destaque!', '🌟 Perfeito pro fim do dia!'],
  };
  const lista = mensagens[ctx.periodo] || ['✨ Produto em destaque!', '🔥 Escolha do dia!', '⭐ Experimente hoje!'];
  const titulo_escolhido = lista[Math.floor(Math.random() * lista.length)];

  if (prod.imagem) {
    imgEl.innerHTML = `<img src="${prod.imagem}" style="width:100%;height:100%;object-fit:cover;border-radius:14px" onerror="this.parentElement.textContent='${prod.emoji||'🍽️'}'">`;
  } else {
    imgEl.textContent = prod.emoji || '🍽️';
  }

  titulo.textContent = titulo_escolhido;
  texto.textContent  = `"${ctx.hook}"`;
  const _fmtP = v => 'R$ ' + parseFloat(v).toFixed(2).replace('.',',');
  if (btn) btn.textContent = `Quero este! — ${_fmtP(prod.preco)}`;
  if (refresh) { refresh.style.animation = ''; refresh.style.transform = 'rotate(0deg)'; }
}

window.rangoSugereAdicionar = function rangoSugereAdicionar() {
  if (!_sugereProduto) return;
  addToCart(Number(_sugereProduto.id));
}

let combo        = { main: null, drink: null, snack: null };
let pollingTimer = null;
const POINTS_PER_REAL   = 0.5;
const LEVEL_THRESHOLD   = 100;

const fmt_brl = v => 'R$ ' + parseFloat(v).toFixed(2).replace('.', ',');


async function doLogout() {
  await API.auth.logout();
  sessionStorage.removeItem('rango-user');
  window.location.href = 'rango-login.html';
}


async function carregarDados() {
  try {
    
    const authRes = await API.auth.check();
    if (!authRes.ok) { window.location.replace('rango-login.html'); return; }
    usuario = authRes.dados.usuario;
    aplicarUsuarioNaUI();


    iniciarPollingStatus();

   
    const ptRes = await API.usuario.pontos();
    if (ptRes.ok) {
      rangoPoints   = parseFloat(ptRes.dados.rango_points  || 0);
      pontos_ganhos = parseFloat(ptRes.dados.pontos_ganhos || 0);

      const spentEl  = document.getElementById('stat-spent');
      const orderEl  = document.getElementById('stat-orders');
      if (spentEl) spentEl.textContent = fmt_brl(ptRes.dados.total_gasto_mes || 0);
      if (orderEl) orderEl.textContent = ptRes.dados.pedidos_mes || 0;
    }

    
    const [catRes, prodRes] = await Promise.all([
      API.categorias.listar(),
      API.produtos.listar(),
    ]);

    if (catRes.ok)  categorias = catRes.dados;
    if (prodRes.ok) produtos   = prodRes.dados;

    renderCategories();
    renderProducts();
    rangoSugereNovo(); 

   
    const _seed = await API.pedidos.meus();
    if (_seed.ok) _seed.dados.forEach(p => { _statusAnterior[String(p.id)] = p.status; });
    await carregarPedidos();
    renderOrders();
    renderHistory_pontos();
    updatePointsUI();

   
    const nome = (usuario.nome || 'Aluno').split(' ')[0];
    setTimeout(() => showToast(`Bem-vindo, ${nome}! 👋`, 'success'), 400);

  } catch (e) {
    showToast('Falha ao carregar dados.', 'error');
    console.error(e);
  }
}

async function carregarPedidos() {
  const res = await API.pedidos.meus();
  if (!res.ok) return;
  orders = { pendentes: [], confirmados: [], historico: [] };
  const todos = res.dados;
  for (const p of todos) {
    if (p.status === 'pendente')              orders.pendentes.push(mapPedido(p));
    else if (['confirmado','preparando','pronto'].includes(p.status)) orders.confirmados.push(mapPedido(p));
    else                                      orders.historico.push(mapPedido(p));
  }
  
  const ativos = todos.filter(p => !['entregue','cancelado'].includes(p.status));
  verificarMudancasStatus(ativos);

  const total = orders.pendentes.length;
  const badge = document.getElementById('pending-count');
  if (badge) {
    badge.style.display = total > 0 ? 'inline-flex' : 'none';
    badge.textContent   = total;
  }
}

function mapPedido(p) {
  return {
    id:    '#' + String(p.id).padStart(6, '0'),
    items: (p.itens || []).map(i => ({
      name:  i.produto_nome,
      emoji: i.produto_emoji || '🍽️',
      qty:   parseInt(i.quantidade),
      price: parseFloat(i.preco_unitario),
    })),
    total:  parseFloat(p.total),
    date:   p.created_at ? new Date(p.created_at).toLocaleDateString('pt-BR') : '—',
    status: p.status,
    code:   p.codigo,
    pix_qrcode:    p.asaas_pix_qrcode   || null,
    pix_copypaste: p.asaas_pix_copypaste|| null,
    invoice_url:   p.asaas_invoice_url  || null,
    db_id:         p.id,
  };
}

function aplicarUsuarioNaUI() {
  if (!usuario) return;
  const iniciais = usuario.nome.split(' ').map(w => w[0]).slice(0, 2).join('');
  document.querySelectorAll('.avatar-btn').forEach(el => el.textContent = iniciais);
  const ph = document.querySelector('.profile-meta h4');
  if (ph) ph.textContent = usuario.nome;
  const pm = document.querySelector('.profile-meta p');
  if (pm) pm.textContent = `Matrícula: ${usuario.matricula} • ${usuario.tipo === 'aluno' ? 'Aluno' : 'Admin'}`;
  const pa = document.querySelector('.profile-avatar');
  if (pa && pa.childNodes[0]) pa.childNodes[0].textContent = iniciais;
  const greet = document.querySelector('.estab-header p strong');
  if (greet) greet.textContent = usuario.nome.split(' ')[0];
  carregarPerfil();
}


function carregarPerfil() {
  if (!usuario) return;
  const nomeEl = document.getElementById('profile-nome');
  const matEl  = document.getElementById('profile-matricula');
  const mailEl = document.getElementById('profile-email');
  if (nomeEl) nomeEl.value = usuario.nome || '';
  if (matEl)  matEl.value  = usuario.matricula || '';
  if (mailEl) mailEl.value = usuario.email || '';
}


async function salvarPerfil() {
  const msg  = document.getElementById('perfil-msg');
  const nome = document.getElementById('profile-nome')?.value.trim();
  const email= document.getElementById('profile-email')?.value.trim();
  if (!nome) {
    if (msg) { msg.textContent='Informe seu nome.'; msg.style.cssText='display:block;background:rgba(255,77,77,.1);color:#ff4d4d;border:1px solid rgba(255,77,77,.25)'; }
    return;
  }
  const res = await API.usuario.perfil({ nome, email });
  if (!res.ok) {
    if (msg) { msg.textContent=res.erro||'Erro ao salvar.'; msg.style.cssText='display:block;background:rgba(255,77,77,.1);color:#ff4d4d;border:1px solid rgba(255,77,77,.25)'; }
    return;
  }

  usuario.nome  = nome;
  usuario.email = email;
  sessionStorage.setItem('rango-user', JSON.stringify(usuario));
  aplicarUsuarioNaUI();
  if (msg) { msg.textContent='Perfil atualizado! ✅'; msg.style.cssText='display:block;background:rgba(88,214,141,.1);color:#58d68d;border:1px solid rgba(88,214,141,.25)'; }
  setTimeout(() => { if (msg) msg.style.display='none'; }, 3000);
  showToast('Perfil atualizado! ✅', 'success');
}


async function alterarSenhaAluno() {
  const msg   = document.getElementById('seg-msg');
  const atual = document.getElementById('seg-senha-atual')?.value;
  const nova  = document.getElementById('seg-senha-nova')?.value;
  const conf  = document.getElementById('seg-senha-conf')?.value;
  function showSeg(m, ok) {
    if (!msg) return;
    msg.textContent = m;
    msg.style.cssText = `display:block;background:rgba(${ok?'88,214,141':'255,77,77'},.1);color:${ok?'#58d68d':'#ff4d4d'};border:1px solid rgba(${ok?'88,214,141':'255,77,77'},.25)`;
  }
  if (!atual || !nova) { showSeg('Preencha todos os campos.', false); return; }
  if (nova.length < 8) { showSeg('Nova senha deve ter mín. 8 caracteres.', false); return; }
  if (nova !== conf)   { showSeg('As senhas não coincidem.', false); return; }
  const res = await API.usuario.perfil({ senha_atual: atual, senha_nova: nova });
  if (!res.ok) { showSeg(res.erro || 'Erro ao alterar senha.', false); return; }
  ['seg-senha-atual','seg-senha-nova','seg-senha-conf'].forEach(id => {
    const el = document.getElementById(id); if (el) el.value = '';
  });
  showSeg('Senha alterada com sucesso! ✅', true);
  setTimeout(() => { if (msg) msg.style.display='none'; }, 4000);
  showToast('Senha alterada! ✅', 'success');
}


function showScreen(name) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById('screen-' + name)?.classList.add('active');
  document.querySelectorAll('.nav-tab').forEach((t, i) => {
    const screens = ['estabelecimento', 'pontos', 'pedidos', 'configuracoes'];
    t.classList.toggle('active', screens[i] === name);
  });
  document.querySelectorAll('.mobile-nav-btn').forEach(b => b.classList.remove('active'));
  const mmap = { estabelecimento:'mnav-cantina', pontos:'mnav-pontos', pedidos:'mnav-pedidos', configuracoes:'mnav-config' };
  if (mmap[name]) document.getElementById(mmap[name])?.classList.add('active');


  if (name === 'pedidos') carregarPedidos().then(renderOrders);
}
function showOrderTab(tab, btn) {
  document.querySelectorAll('.order-tab').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('#screen-pedidos .sub-panel').forEach(p => p.classList.remove('active'));
  document.getElementById('orders-' + tab)?.classList.add('active');
}
function showSettingsPanel(panel, btn) {
  document.querySelectorAll('.settings-nav-item').forEach(b => b.classList.remove('active'));
  btn.classList.add('active');
  document.querySelectorAll('.settings-panel .sub-panel').forEach(p => p.classList.remove('active'));
  document.getElementById('settings-' + panel)?.classList.add('active');
}

function renderCategories() {
  const el = document.getElementById('categories-scroll');
  if (!el) return;
  const cats = [{ nome: 'Todos', icone: '' }, ...categorias];
  el.innerHTML = cats.map(c =>
    `<button class="cat-chip ${c.nome === activeCategory ? 'active' : ''}"
      onclick="filterCat('${c.nome}', this)">
       ${c.icone ? c.icone + ' ' : ''}${c.nome}
     </button>`
  ).join('');
}


function renderProducts(filter = '') {
  const el = document.getElementById('products-grid');
  if (!el) return;
  let list = produtos;
  if (activeCategory !== 'Todos') {
    const cat = categorias.find(c => c.nome === activeCategory);
    if (cat) list = list.filter(p => parseInt(p.categoria_id) === parseInt(cat.id));
  }
  if (filter) list = list.filter(p =>
    p.nome.toLowerCase().includes(filter.toLowerCase()) ||
    (p.descricao || '').toLowerCase().includes(filter.toLowerCase())
  );
  if (!list.length) {
    el.innerHTML = `<div class="empty-state" style="grid-column:1/-1"><div class="empty-state-emoji">🔍</div><p>Nenhum produto encontrado.</p></div>`;
    return;
  }
  el.innerHTML = list.map(p => {
    const inStock = p.em_estoque !== false && Number(p.estoque) > 0;
    const pid = Number(p.id);
    return `<div class="product-card${inStock?'':' esgotado'}" data-pid="${pid}" style="${inStock?'':'opacity:.55;pointer-events:none'}">
      ${!inStock ? '<div class="out-badge">Esgotado</div>' : ''}
      <div class="product-img" style="${p.imagem ? 'padding:0;overflow:hidden' : ''}">
        ${p.imagem
          ? `<img src="${p.imagem}" alt="${p.nome}"
               style="width:100%;height:100%;object-fit:cover;border-radius:inherit"
               onerror="this.parentElement.innerHTML='${p.emoji || '🍽️'}';">`
          : (p.emoji || '🍽️')}
      </div>
      <div class="product-info">
        <div class="product-name">${p.nome}</div>
        <div class="product-desc">${p.descricao || ''}</div>
        <div class="product-footer">
          <div class="product-price">${fmt_brl(p.preco)}</div>
          ${inStock ? `<button class="add-btn" data-pid="${pid}">+</button>` : '<span style="font-size:.72rem;color:var(--muted)">Indisponível</span>'}
        </div>
      </div>
    </div>`;
  }).join('');

  el.querySelectorAll('.product-card:not(.esgotado)').forEach(card => {
    card.addEventListener('click', e => {
      if (e.target.closest('.add-btn')) return;
      addToCart(Number(card.dataset.pid));
    });
    card.querySelector('.add-btn')?.addEventListener('click', e => {
      e.stopPropagation();
      addToCart(Number(card.dataset.pid));
    });
  });
}

function filterCat(cat, btn) {
  activeCategory = cat;
  document.querySelectorAll('.cat-chip').forEach(c => c.classList.remove('active'));
  btn.classList.add('active');
  renderProducts(document.getElementById('search-input')?.value || '');
}
function filterProducts(val) { renderProducts(val); }

function addToCart(id) {
  id = parseInt(id);
  const p = produtos.find(x => parseInt(x.id) === id);
  if (!p) return;

  const ex = cart.find(x => parseInt(x.id) === id);
  if (ex) {
    ex.qty++;
  } else {

    cart.push({ ...p, id: parseInt(p.id), qty: 1 });
  }
  updateCartUI();
  showToast(`${p.emoji || '🍽️'} ${p.nome} adicionado!`, 'success');
}
function changeQty(id, delta) {
  id = parseInt(id);
  const idx = cart.findIndex(x => parseInt(x.id) === id);
  if (idx === -1) return;
  cart[idx].qty += delta;
  if (cart[idx].qty <= 0) cart.splice(idx, 1);
  updateCartUI();
}
function updateCartUI() {
  const total = cart.reduce((s, i) => s + parseFloat(i.preco) * i.qty, 0);
  const count = cart.reduce((s, i) => s + i.qty, 0);
  const fl = document.getElementById('cart-float');
  document.getElementById('cart-count').textContent = count;
  document.getElementById('cart-float-total').textContent = fmt_brl(total);
  if (fl) fl.classList.toggle('show', count > 0);
  renderCartItems();
}
function renderCartItems() {
  const el = document.getElementById('cart-items-list');
  if (!el) return;
  if (!cart.length) {
    el.innerHTML = '<div class="empty-state"><div class="empty-state-emoji">🛒</div><p>Carrinho vazio</p></div>';
  } else {
    el.innerHTML = cart.map(i => `
      <div class="cart-item">
        <div class="cart-item-emoji">${i.emoji || '🍽️'}</div>
        <div class="cart-item-info">
          <div class="cart-item-name">${i.nome}</div>
          <div class="cart-item-price">${fmt_brl(parseFloat(i.preco) * i.qty)}</div>
        </div>
        <div class="qty-control">
          <button class="qty-btn" onclick="changeQty(${i.id},-1)">−</button>
          <span class="qty-num">${i.qty}</span>
          <button class="qty-btn" onclick="changeQty(${i.id},1)">+</button>
        </div>
      </div>`).join('');
  }
  const total = cart.reduce((s, i) => s + parseFloat(i.preco) * i.qty, 0);
  const sub   = document.getElementById('cart-sub');
  const tot   = document.getElementById('cart-total-display');
  if (sub) sub.textContent = fmt_brl(total);
  if (tot) tot.textContent = fmt_brl(total);
}
function openCart() {
  renderCartItems();
  document.getElementById('cart-overlay')?.classList.add('open');
  document.getElementById('cart-sidebar')?.classList.add('open');
}
function closeCart() {
  document.getElementById('cart-overlay')?.classList.remove('open');
  document.getElementById('cart-sidebar')?.classList.remove('open');
}


let selectedPayMethod = null;

const PHYSICAL_METHODS = ['cartao_credito','cartao_debito','dinheiro','tap'];
const PAY_LABELS = {
  pix: 'PIX', cartao_credito: 'cartão', cartao_debito: 'cartão débito',
  dinheiro: 'dinheiro', tap: 'Tap to Pay'
};

async function checkout() {
  if (!cart.length) { showToast('Carrinho vazio!', 'error'); return; }

  const hRes = await API.horarios.check().catch(() => null);
  if (hRes?.ok && hRes.dados?.aberto === false) {
    const prox = hRes.dados.proximo_turno;
    const msg  = prox
      ? `⏰ Cantina fechada. Abre às ${prox.abre_em}.`
      : '⏰ Cantina fechada no momento.';
    showToast(msg, 'error');

    const banner = document.getElementById('cantina-fechada-banner');
    if (banner) { banner.style.display='flex'; banner.querySelector('span').textContent=msg; }
    return;
  }

  selectedPayMethod = null;
  document.querySelectorAll('.pay-opt').forEach(b => b.classList.remove('selected'));
  document.getElementById('pay-physical-notice').style.display = 'none';
  const btn = document.getElementById('pay-confirm-btn');
  if (btn) {
    btn.disabled = true;
    btn.textContent = 'SELECIONE UMA FORMA';
    btn.style.background = 'rgba(255,122,0,.3)';
    btn.style.color = 'rgba(255,255,255,.4)';
    btn.style.cursor = 'not-allowed';
  }
  const total = cart.reduce((s,i) => s + parseFloat(i.preco)*i.qty, 0);
  const tot = document.getElementById('pay-modal-total');
  if (tot) tot.textContent = fmt_brl(total);
  closeCart();
  document.getElementById('payment-select-modal')?.classList.add('open');
}

function closePaymentModal() {
  document.getElementById('payment-select-modal')?.classList.remove('open');
}

function selectPayOpt(method, el) {
  selectedPayMethod = method;
  document.querySelectorAll('.pay-opt').forEach(b => b.classList.remove('selected'));
  el.classList.add('selected');

  const notice = document.getElementById('pay-physical-notice');
  const methodLabel = document.getElementById('pay-physical-method');
  const btn = document.getElementById('pay-confirm-btn');

  if (PHYSICAL_METHODS.includes(method)) {
    if (methodLabel) methodLabel.textContent = PAY_LABELS[method] || method;
    if (notice) notice.style.display = 'block';
    if (btn) btn.textContent = 'CONFIRMAR PEDIDO';
  } else {
    if (notice) notice.style.display = 'none';
    if (btn) btn.textContent = method === 'pix' ? 'GERAR QR CODE PIX' : 'CONFIRMAR PEDIDO';
  }
  if (btn) {
    btn.disabled = false;
    btn.style.background = 'linear-gradient(135deg,#ff7a00,#ff5500)';
    btn.style.color = '#fff';
    btn.style.cursor = 'pointer';
  }
}

function setPayMethod(method, btn) { selectPayOpt(method, btn); }


async function confirmPaymentAndCheckout() {
  if (!selectedPayMethod) return;
  closePaymentModal();
  if (!cart.length) { showToast('Carrinho vazio!', 'error'); return; }

  const itens = cart.map(i => ({
    produto_id: i.id,
    quantidade: i.qty,
  }));

  showToast('Criando pedido...', 'success');

  const res = await API.pedidos.criar({
    itens,
    forma_pagamento: selectedPayMethod,
    origem: 'app',
    cliente_nome: usuario?.nome || 'Aluno',
  });

  if (!res.ok) {
    showToast(res.erro || 'Erro ao criar pedido.', 'error');
    openCart();
    return;
  }

  const pedido = res.dados;
  cart = [];
  updateCartUI();


  const codeEl = document.getElementById('order-code-display');
  if (codeEl) codeEl.textContent = pedido.codigo;


  const pagamento = pedido.pagamento;
  const pixBlock = document.getElementById('pix-payment-block');
  if (pagamento?.pix_qrcode && pixBlock) {
    pixBlock.style.display = 'block';
    const qrImg = document.getElementById('pix-qrcode-img');
    if (qrImg) qrImg.src = 'data:image/png;base64,' + pagamento.pix_qrcode;
    const copyBtn = document.getElementById('pix-copypaste');
    if (copyBtn) copyBtn.setAttribute('data-pix', pagamento.pix_copypaste || '');
  } else if (pixBlock && !PHYSICAL_METHODS.includes(selectedPayMethod)) {

    pixBlock.style.display = 'block';
    const qrImg = document.getElementById('pix-qrcode-img');
    if (qrImg) {
      qrImg.style.display = 'none';
      qrImg.insertAdjacentHTML('afterend',
        '<div id="pix-qr-loading" style="width:160px;height:160px;border-radius:12px;border:1px solid var(--border);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;background:var(--surface);margin:0 auto">' +
        '<div style="font-size:1.8rem">⏳</div>' +
        '<div style="font-size:.72rem;color:var(--muted);font-weight:600">Gerando QR...</div></div>'
      );
    }
    buscarQRCode(pedido.id);
  } else if (pixBlock) {
    pixBlock.style.display = 'none';
  }

  const successModal = document.getElementById('order-success');
  if (successModal) successModal.dataset.dbId = pedido.id;

  if (PHYSICAL_METHODS.includes(selectedPayMethod)) {
    const succ_emoji = document.querySelector('#order-success .success-emoji');
    const succ_title = document.querySelector('#order-success h3');
    const succ_desc  = document.querySelector('#order-success p');
    const pixBlock   = document.getElementById('pix-payment-block');
    if (succ_emoji) succ_emoji.textContent = '🧾';
    if (succ_title) succ_title.textContent = 'Pedido Registrado!';
    if (succ_desc)  succ_desc.innerHTML =
      `⚠️ Dirija-se ao balcão e pague com <strong>${PAY_LABELS[selectedPayMethod] || selectedPayMethod}</strong> na maquininha.<br><small style="color:var(--muted)">Seu pedido será preparado após a confirmação do pagamento.</small>`;
    if (pixBlock) pixBlock.style.display = 'none';
  } else {
  
    const succ_emoji = document.querySelector('#order-success .success-emoji');
    const succ_title = document.querySelector('#order-success h3');
    const succ_desc  = document.querySelector('#order-success p');
    if (succ_emoji) succ_emoji.textContent = '🎉';
    if (succ_title) succ_title.textContent = 'Pedido Realizado!';
    if (succ_desc)  succ_desc.textContent  = 'Aguarde a confirmação e fique de olho no seu código';
  }

  document.getElementById('order-success')?.classList.add('open');


  if (!PHYSICAL_METHODS.includes(selectedPayMethod)) iniciarPollingPagamento(pedido.id);

  await carregarPedidos();
  renderOrders();
  updatePointsUI();
}

function copiarPix() {
  const btn = document.getElementById('pix-copypaste');
  const txt = btn?.getAttribute('data-pix');
  if (!txt) return;
  navigator.clipboard.writeText(txt).then(() => showToast('PIX copiado! 📋', 'success'));
}


function iniciarPollingPagamento(dbId) {
  clearInterval(pollingTimer);
  let tentativas = 0;
  pollingTimer = setInterval(async () => {
    if (tentativas++ > 30) { clearInterval(pollingTimer); return; } 
    const res = await API.pedidos.verificarPagto(dbId);
    if (res?.ok && res.dados?.pago) {
      clearInterval(pollingTimer);
      showToast('💚 Pagamento confirmado!', 'success');
      const badge = document.getElementById('pix-status-badge');
      if (badge) { badge.textContent = '✅ Pago'; badge.style.color = '#58d68d'; }
      await carregarPedidos();
      renderOrders();
      const ptRes = await API.usuario.pontos();
      if (ptRes.ok) {
        rangoPoints   = parseFloat(ptRes.dados.rango_points);
        pontos_ganhos = parseFloat(ptRes.dados.pontos_ganhos);
        const spentEl = document.getElementById('stat-spent');
        const orderEl = document.getElementById('stat-orders');
        if (spentEl) spentEl.textContent = fmt_brl(ptRes.dados.total_gasto_mes || 0);
        if (orderEl) orderEl.textContent = ptRes.dados.pedidos_mes || 0;
        updatePointsUI();
      }
    }
  }, 10000);
}

async function buscarQRCode(dbId) {
  let tentativas = 0;
  const maxTentativas = 8; 
  const timer = setInterval(async () => {
    tentativas++;
    try {
      const res = await API.pedidos.qrcode(dbId);
      if (res?.ok && res.dados?.pix_qrcode) {
        clearInterval(timer);
        document.getElementById('pix-qr-loading')?.remove();
        const qrImg = document.getElementById('pix-qrcode-img');
        if (qrImg) { qrImg.src = 'data:image/png;base64,' + res.dados.pix_qrcode; qrImg.style.display = ''; }
        const copyBtn = document.getElementById('pix-copypaste');
        if (copyBtn) copyBtn.setAttribute('data-pix', res.dados.pix_copypaste || '');
        return;
      }

      if (!res?.ok && res?.erro && !res.erro.includes('não disponível') && !res.erro.includes('Tente novamente')) {
        clearInterval(timer);
        document.getElementById('pix-qr-loading')?.remove();
        showToast('⚠️ ' + res.erro, 'error');
        return;
      }
    } catch(e) {}
    if (tentativas >= maxTentativas) {
      clearInterval(timer);
      document.getElementById('pix-qr-loading')?.remove();
      const qrImg = document.getElementById('pix-qrcode-img');
      if (qrImg) { qrImg.style.display = ''; qrImg.alt = 'QR não disponível'; }
      showToast('⚠️ Não foi possível gerar o QR Code. Tente copiar o código PIX.', 'error');
    }
  }, 3000);
}

function closeOrderSuccess() {
  clearInterval(pollingTimer);
  document.getElementById('order-success')?.classList.remove('open');

  const succ_emoji = document.querySelector('#order-success .success-emoji');
  const succ_title = document.querySelector('#order-success h3');
  const succ_desc  = document.querySelector('#order-success p');
  if (succ_emoji) succ_emoji.textContent = '🎉';
  if (succ_title) succ_title.textContent = 'Pedido Realizado!';
  if (succ_desc)  succ_desc.textContent  = 'Aguarde a confirmação e fique de olho no seu código';
  showScreen('pedidos');
}


function updatePointsUI() {
  const pts = Math.floor(rangoPoints);
  document.getElementById('nav-points')?.setAttribute && (document.getElementById('nav-points').textContent = pts + ' pts');
  document.getElementById('points-display') && (document.getElementById('points-display').textContent = pts);
  document.getElementById('stat-points-earned') && (document.getElementById('stat-points-earned').textContent = Math.floor(pontos_ganhos));
 
  const progress = rangoPoints % LEVEL_THRESHOLD;
  const pct = Math.round((progress / LEVEL_THRESHOLD) * 100);
  const pctEl = document.getElementById('points-pct');
  const barEl = document.getElementById('points-bar');
  if (pctEl) pctEl.textContent = pct + '%';
  if (barEl) barEl.style.width = pct + '%';
  const rem = Math.ceil(LEVEL_THRESHOLD - progress);
  const hintEl = document.getElementById('points-hint');
  if (hintEl) hintEl.textContent = `Ganhe mais ${rem} pontos para o próximo cupom!`;
  updateRewardLocks();
}
function updateRewardLocks() {
  CUPOM_CATALOGO.forEach(c => {
    document.getElementById('reward-'+c.id)?.classList.toggle('locked', rangoPoints < c.custo);
  });
}
async function redeemReward(catalogo_id, el) {
  if (!catalogo_id) return;
  const item = CUPOM_CATALOGO.find(c => c.id === catalogo_id);
  if (!item) return;
  if (rangoPoints < item.custo) {
    showToast(`Você precisa de ${item.custo} pontos. Você tem ${Math.floor(rangoPoints)}.`, 'error');
    return;
  }
  if (!confirm(`Gerar cupom "${item.nome}" por ${item.custo} pontos?`)) return;
  const res = await API.cupons.gerar(catalogo_id);
  if (!res.ok) { showToast(res.erro || 'Erro ao gerar cupom.', 'error'); return; }
  rangoPoints = parseFloat(res.dados.pontos_restantes || 0);
  updatePointsUI();
  showToast(`Cupom ${res.dados.codigo} gerado! 🎟️ Válido por 30 dias.`, 'success');
  renderHistory_pontos();
  renderMeusCupons();

  showCupomModal(res.dados);
}
function openRedeemModal() { renderMeusCupons(); }

function showCupomModal(cupom) {
  const overlay = document.getElementById('cupom-modal-overlay');
  if (!overlay) return;
  const codeEl = document.getElementById('cupom-modal-code');
  const descEl = document.getElementById('cupom-modal-desc');
  const expEl  = document.getElementById('cupom-modal-exp');
  if (codeEl) codeEl.textContent = cupom.codigo;
  if (descEl) descEl.textContent = cupom.descricao;
  if (expEl)  expEl.textContent  = `Válido até ${new Date(cupom.expira).toLocaleDateString('pt-BR')}`;
  overlay.classList.add('open');
}
function closeCupomModal() {
  document.getElementById('cupom-modal-overlay')?.classList.remove('open');
}

async function renderMeusCupons() {
  const lista = document.getElementById('meus-cupons-lista');
  if (!lista) return;
  lista.innerHTML = '<div style="color:var(--muted);font-size:.8rem;text-align:center;padding:16px">Carregando...</div>';
  const res = await API.cupons.meus();
  if (!res.ok || !res.dados.cupons.length) {
    lista.innerHTML = '<div class="empty-state"><div class="empty-state-emoji">🎫</div><p>Nenhum cupom ativo. Resgate abaixo!</p></div>';
    return;
  }
  lista.innerHTML = res.dados.cupons.map(c => `
    <div style="display:flex;align-items:center;gap:12px;padding:12px 14px;background:var(--surface);border:1px solid rgba(255,122,0,.2);border-radius:12px;margin-bottom:8px">
      <div style="font-size:1.4rem;flex-shrink:0">${c.tipo==='percentual'?'🏷️':'💸'}</div>
      <div style="flex:1">
        <div style="font-weight:700;font-size:.9rem">${c.descricao}</div>
        <div style="font-family:'Bebas Neue',sans-serif;font-size:1.2rem;color:var(--orange);letter-spacing:3px">${c.codigo}</div>
        <div style="font-size:.7rem;color:var(--muted)">${c.tipo==='percentual'?c.valor+'% OFF':'R$'+parseFloat(c.valor).toFixed(2)+' OFF'} · Expira ${new Date(c.expires_at).toLocaleDateString('pt-BR')}</div>
      </div>
      <button onclick="navigator.clipboard.writeText('${c.codigo}').then(()=>showToast('Código copiado!','success'))"
        style="background:none;border:1px solid var(--border);border-radius:8px;padding:6px 10px;color:var(--muted);cursor:pointer;font-size:.8rem">📋</button>
    </div>`).join('');
}

